//! Boris designation's retained Techno tint timers and phase.
//!
//! Native `TechnoClass::StartAirstrikeTimer` 0070E300, StopAirstrikeTimer
//! 0070E340, UpdateAirstrikeTint 0070E920 and the second half of
//! GetEffectTintIntensity 0070E4B0. Original numeric/RNG controls are in
//! `tools/airstrike_tint.json`, generated by `tools/superweapon_oracle.py`.
//! The marker owner supplies admission; the outer timer never gates updating.

use std::hash::{Hash, Hasher};

use crate::sim::rng::SimRng;
use crate::sim::timer::CdTimer;

/// Techno+1A8 outer timer, +1B4 phase timer and +1C0 phase. Separate from
/// Iron Curtain: both advance in native Techno AI, Iron first, on one stream.
#[derive(Debug, Clone, Default, PartialEq, Eq, serde::Serialize, serde::Deserialize)]
pub struct AirstrikeTintState {
    timer: CdTimer,
    tint_timer: CdTimer,
    tint_stage: u8,
}

impl AirstrikeTintState {
    /// 0070E300 resets the phase and starts the outer timer, retaining the
    /// phase timer until phase zero overwrites it at the next admitted AI.
    pub fn start(&mut self, frame: i32, duration: i32) {
        self.timer.start(frame, duration);
        self.tint_stage = 0;
    }

    /// 0070E340 starts the outer timer with zero; it does not reset the phase.
    pub(crate) fn stop(&mut self, frame: i32) {
        self.timer.start(frame, 0);
    }

    /// 0070E920 admits only a building with a marker whose manager targets
    /// that building. Losing admission resets only the phase. Stage two
    /// draws Scenario RandomRanged(-5,5) once (0070EA4B); no other stage draws.
    pub fn update_tint(&mut self, frame: i32, active: bool, rng: &mut SimRng) {
        if !active {
            self.tint_stage = 0;
            return;
        }
        let ran_out = self.tint_timer.expired(frame);
        let next = match self.tint_stage {
            0 => Some((1, 6)),
            1 => ran_out.then_some((2, 4)),
            2 => ran_out.then(|| (3, 20 + rng.next_range_i32_inclusive(-5, 5))),
            3 => ran_out.then_some((4, 64)),
            4 => ran_out.then_some((5, 64)),
            5 if ran_out && self.timer.remaining(frame) < 158 => {
                self.tint_stage = 6;
                None
            }
            5 => ran_out.then_some((4, 64)),
            6 => (self.timer.remaining(frame) <= 30).then_some((7, 6)),
            7 => ran_out.then_some((8, 4)),
            8 => ran_out.then_some((9, 20)),
            9 if !ran_out => None,
            _ => {
                self.tint_stage = 10;
                None
            }
        };
        if let Some((stage, duration)) = next {
            self.tint_stage = stage;
            self.tint_timer.start(frame, duration);
        }
    }

    /// ScaleByAirstrikeTintPhase 0070E4B0: called after Iron's scaling and
    /// cap, even if the airstrike marker was lost since the last AI. Signed
    /// division truncates toward zero; products and shifts wrap in 32 bits.
    pub fn effect_tint_intensity(&self, intensity: i32, frame: i32) -> i32 {
        let left = self.tint_timer.remaining(frame);
        let scale = match self.tint_stage {
            1 | 7 => (12i32.wrapping_sub(left) << 8) / 6,
            2 | 8 => 512,
            3 | 9 => (left.wrapping_add(20) << 8) / 20,
            4 => (128i32.wrapping_sub(left) << 8) / 64,
            5 => (left.wrapping_add(64) << 8) / 64,
            6 => 256,
            _ => return intensity,
        };
        (scale.wrapping_mul(intensity) >> 8).min(2000)
    }

    pub(crate) fn hash_state(&self, hasher: &mut impl Hasher) {
        if self == &Self::default() {
            return;
        }
        b"airstrike-tint".hash(hasher);
        self.timer.hash(hasher);
        self.tint_timer.hash(hasher);
        self.tint_stage.hash(hasher);
    }

    #[cfg(any(test, feature = "test-support"))]
    pub(crate) fn with_tint(tint_stage: u8, tint_timer: CdTimer) -> Self {
        Self {
            tint_stage,
            tint_timer,
            ..Self::default()
        }
    }
}

